import * as React from 'react';
import { 
  Panel, 
  PanelType, 
  Dropdown, 
  IDropdownOption, 
  PrimaryButton, 
  DefaultButton,
  Stack,
  IStackTokens,
  MessageBar,
  MessageBarType
} from '@fluentui/react';
import { IInventoryItem } from '../models/IInventoryItem';
import { IEmployee } from '../models/IEmployee';

export interface IAssetAssignmentFormProps {
  isOpen: boolean;
  onClose: () => void;
  employee: IEmployee | undefined;
  availableAssets: IInventoryItem[];
  onAssignAssets: (employee: IEmployee, assetIds: string[]) => Promise<void>;
}

export const AssetAssignmentForm: React.FC<IAssetAssignmentFormProps> = (props) => {
  const stackTokens: IStackTokens = { childrenGap: 15 };
  const [selectedAssetIds, setSelectedAssetIds] = React.useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | undefined>();

  // Reset state when opened with a new employee
  React.useEffect(() => {
    if (props.isOpen) {
      setSelectedAssetIds([]);
      setError(undefined);
    }
  }, [props.isOpen, props.employee]);

  const assetOptions: IDropdownOption[] = props.availableAssets.map(asset => ({
    key: asset.id,
    text: `${asset.assetName || asset.title} (${asset.serialNumber || 'No SN'}) - ${asset.assetType}`
  }));

  const onDropdownChange = (event: React.FormEvent<HTMLDivElement>, item: IDropdownOption | undefined): void => {
    if (item) {
      setSelectedAssetIds(
        item.selected ? [...selectedAssetIds, item.key as string] : selectedAssetIds.filter(key => key !== item.key),
      );
    }
  };

  const onSave = async () => {
    if (!props.employee || selectedAssetIds.length === 0) return;
    
    setIsSubmitting(true);
    setError(undefined);
    try {
      await props.onAssignAssets(props.employee, selectedAssetIds);
      props.onClose();
    } catch (err: any) {
      setError(err.message || 'An error occurred while assigning assets.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Panel
      isOpen={props.isOpen}
      onDismiss={props.onClose}
      type={PanelType.medium}
      headerText={props.employee ? `Assign Assets to ${props.employee.name}` : 'Assign Assets'}
      closeButtonAriaLabel="Close"
    >
      <Stack tokens={stackTokens}>
        <p style={{ margin: 0, color: '#4b5563', fontSize: '0.9rem' }}>
          Select one or multiple available assets to directly assign to this employee.
        </p>

        {error && (
          <MessageBar messageBarType={MessageBarType.error} onDismiss={() => setError(undefined)}>
            {error}
          </MessageBar>
        )}

        <Dropdown
          placeholder="Select available assets"
          label="Available Assets"
          selectedKeys={selectedAssetIds}
          onChange={onDropdownChange}
          multiSelect
          options={assetOptions}
          disabled={assetOptions.length === 0 || isSubmitting}
        />
        
        {assetOptions.length === 0 && (
          <MessageBar messageBarType={MessageBarType.warning}>
            There are no available assets in stock. Please add new assets first.
          </MessageBar>
        )}

        <Stack horizontal tokens={stackTokens} style={{ marginTop: 20 }}>
          <PrimaryButton 
            text="Confirm Assignment" 
            onClick={onSave} 
            disabled={selectedAssetIds.length === 0 || isSubmitting} 
          />
          <DefaultButton text="Cancel" onClick={props.onClose} disabled={isSubmitting} />
        </Stack>
      </Stack>
    </Panel>
  );
};
